export function run({ items }) {
  const DAY_MS = 24 * 60 * 60 * 1000;
  const now = Date.now();
  const seen = new Set();
  const unique = [];
  for (const it of items || []) {
    const ts = Date.parse(it.pubDate || it.date || "");
    if (isNaN(ts) || now - ts > DAY_MS) continue; // freshness guard (filter already applied)
    const key = it.link || it.url || it.title || "";
    if (!key || seen.has(key)) continue;
    seen.add(key);
    unique.push({ it, ts });
  }
  // 8 most recent items, newest first so the oldest of the 8 ends up last
  unique.sort((a, b) => b.ts - a.ts);
  const top = unique.slice(0, 8);
  const digest = top
    .map(({ it, ts }) => {
      const title = String(it.title || "").replace(/\s+/g, " ").trim();
      const source = it.source || it.feed || "unknown";
      const date = new Date(ts).toISOString().slice(0, 16).replace("T", " ");
      const snippet = String(it.description || it.summary || "").replace(/\s+/g, " ").trim().slice(0, 300);
      return "\u2014 " + title + " (" + source + ", " + date + ")\n" + snippet + "\n";
    })
    .join("\n");
  return { digest };
}
